      "60歳女性。右上葉原発性肺腺がんと診断され、右上葉切除術が施行された。その後、術後補助化学療法が施行され経過観察となった。術後4年経過時、胸部CT写真で右鎖骨上窩リンパ節に転移が認められ、再発と診断された。ALK 融合遺伝子陽性が確認されたため、クリゾチニブ250 mg、1日2回の投与による治療が開始された。投与13日目時点でリンパ節の腫瘍は縮小傾向を認めた。各時点における主な検査値は以下のとおりである。\n\n肝機能検査値：投与前、8日目、13日目\nAST（IU/L）：30、100、350\nALT（IU/L）：30、120、400\nALP（IU/L）：200、600、2,000\n総ビリルビン（mg/dL）：1.0、1.1、1.3",
