    caseContext:
      "35歳女性。最近、日中頻尿と尿意切迫感で不眠が続いたので近医を受診した。過活動膀胱症状質問票（OABSS）トータルスコア10点の中等症と診断され、処方1による薬物治療を受けていた。再診時、OABSSトータルスコアは6点と改善したが尿意切迫感が十分に改善しないため、処方2が追加された。\n\n再診時の主な患者情報：血圧 130/60 mmHg、脈拍数 60拍/分、消化器症状なし、肝機能・腎機能正常、電解質異常なし。現在、妊娠はしていない。\n\n（処方1）\nソリフェナシンコハク酸塩錠 5 mg　1回1錠（1日1錠）\n1日1回　朝食後　14日分\n\n（処方2）\nミラベグロン錠 50 mg　1回1錠（1日1錠）\n1日1回　朝食後　14日分\n\n再診7日後、薬剤師が継続的な服薬状況と患者状態を確認し、服薬指導を行うため、患者宅に電話した。",
    field: "実務",

    question:
      "副作用症状としてこの患者に起こる可能性が最も低いのはどれか。1つ選べ。",

    choices: [
    "血圧上昇",
    "尿閉",
    "ふらつき、めまい",
    "便秘",
    "唾液の分泌過多"
    ],

    answer: 4,


    explanation:
      "正答は5です。抗コリン作用をもつ薬剤では、唾液などの分泌はむしろ低下し、口渇が起こりやすくなります。そのため「唾液の分泌過多」は副作用症状として最も起こりにくいと考えられます。尿閉や便秘は抗コリン作用でみられやすい症状です。ふらつき・めまいは中枢作用や血圧変動などで起こることがあります。血圧上昇も薬剤によってはみられる可能性があります。"
