    caseContext:
      "10月14日（月曜日）に小学校において、50名の児童が発熱・嘔吐・下痢の症状で欠席し、翌日にも同様の症状でさらに65名が欠席し児童の多くが病院を受診しているとの連絡が保健所にあった。早速、これらの患者のうち、60名の検体について検査を行ったところ、48名の検体から同一の病因物質を検出した。患者らの共通食は学校給食のみであり、10月11日（金曜日）に遠足のために給食を食べなかった学年に有症者がいないことから、給食が食中毒の原因と断定した。なお、衛生検査用に冷凍保存されていた同じ給食を調べた結果、原材料の鶏肉からも同じ病因物質を検出した。これを顕微鏡で観察したところ、写真の様に細長い、らせん状の形態を示していた。",
