      "正答は4のメタロチオネインです。メタロチオネインはシステインを多く含む低分子タンパク質で、カドミウムなどの重金属と結合し、毒性を弱める働きがあります。重金属中毒の解毒・防御に関わる生体分子として重要です。1のカタラーゼは過酸化水素を分解する酵素、2のグルタチオンペルオキシダーゼは過酸化物の還元に関わる酵素です。3のシトクロムP450は主に薬物代謝に関与し、5のビリルビンはヘム代謝産物で抗酸化作用はありますが、重金属の解毒が主作用ではありません。"
