      "70歳女性。高血圧、心筋梗塞の既往あり。処方1〜処方3の薬剤を服用していたが、脂質異常症の治療効果不十分のため処方4が追加された。現在の身体所見等は以下のとおりである。\n\n身体所見：身長155 cm、体重56 kg、血圧118/75 mmHg、脈拍数67拍/分（整）\n血液検査：AST 30 IU/L、ALT 28 IU/L、血清クレアチニン値0.75 mg/dL、BUN 17 mg/dL、HDL 42 mg/dL、LDL 122 mg/dL、TG（トリグリセリド）110 mg/dL\n\n（処方1）\nアスピリン腸溶錠100 mg　1回1錠（1日1錠）\nラベプラゾールNa錠5 mg　1回1錠（1日1錠）\n1日1回　朝食後　7日分\n\n（処方2）\nテルミサルタン40 mg/アムロジピンベシル酸塩5 mg配合錠\n1回1錠（1日1錠）\n1日1回　朝食後　7日分\n\n（処方3）\nロスバスタチン口腔内崩壊錠10 mg　1回2錠（1日2錠）\n1日1回　朝食後　7日分\n\n（処方4）\nエゼチミブ錠10 mg　1回1錠（1日1錠）\n1日1回　朝食後　7日分",
