    answer: [0, 2],


    explanation:
      "正答は1、3です。介護保険は原則65歳以上が対象ですが、40～64歳の第2号被保険者でも、がん末期や関節リウマチ、パーキンソン病関連疾患などの特定疾病が原因で介護が必要な場合は申請できます。要介護認定は、市町村が行い、認定調査による心身の状態や主治医意見書などをもとに判定されます。2は、申請先は薬局ではなく市町村の窓口です。4は、要介護状態は要介護1～5に区分され、要支援1・2もあります。5は、介護保険が優先されるサービスでは、薬局と患者の相談だけで医療保険との適用を自由に決めるものではありません。"
